package com.asmj.marketplace.advertising;
import java.math.BigDecimal; import java.time.Instant; import org.springframework.data.annotation.Id; import org.springframework.data.mongodb.core.mapping.Document; import org.springframework.data.mongodb.core.index.Indexed;
@Document("advertisement_packages") public class AdPackage { @Id private String id; @Indexed private String placementCode; private String name; private int durationDays; private BigDecimal price=BigDecimal.ZERO; private boolean enabled=true; private Instant updatedAt=Instant.now();
public String getId(){return id;} public void setId(String v){id=v;} public String getPlacementCode(){return placementCode;} public void setPlacementCode(String v){placementCode=v;} public String getName(){return name;} public void setName(String v){name=v;} public int getDurationDays(){return durationDays;} public void setDurationDays(int v){durationDays=v;} public BigDecimal getPrice(){return price;} public void setPrice(BigDecimal v){price=v;} public boolean isEnabled(){return enabled;} public void setEnabled(boolean v){enabled=v;} public Instant getUpdatedAt(){return updatedAt;} public void setUpdatedAt(Instant v){updatedAt=v;} }
